/**
 * 定義を再帰的に固定し、表示や処理から設定値を書き換えないようにする。
 * @param {object} value 定義。
 * @returns {object} 固定した定義。
 */
function freezeDefinition(value) {
  for (const child of Object.values(value)) {
    if (child && typeof child === "object") freezeDefinition(child);
  }
  return Object.freeze(value);
}

/** 釣りの初期調整値。猶予と待機は実時間のミリ秒。 */
export const FISHING_CONFIG = freezeDefinition({
  castsPerSession: 5,
  seaQuadrantSize: 25,
  minBiteWaitMs: 2000,
  maxBiteWaitMs: 5000,
  gaugeStressColor: true,
  gaugeStressAt: 0.3,
});

